#!/usr/sbin/nft -f
flush ruleset

table inet filter {
  chain input {
    type filter hook input priority 0; policy drop;

    ct state established,related accept
    iif lo accept

    # PostgreSQL only from the app subnet and the reporting host
    ip saddr 10.20.1.0/24 tcp dport 5432 accept
    ip saddr 10.20.2.15   tcp dport 5432 accept

    # SSH and metrics only from management
    ip saddr 10.20.9.0/24 tcp dport { 22, 9187 } accept

    # log what we drop, rate limited
    limit rate 5/minute log prefix "nft-drop: " level info
  }
  chain forward { type filter hook forward priority 0; policy drop; }
  chain output  { type filter hook output  priority 0; policy accept; }
}

